INSERT INTO `course` VALUES (68,'Birmingham Academy - AEIS Dự bị Công lập Singapore','birmingham-aeis-du-bi-cong-lap','<blockquote><em style=\"color: rgb(230, 0, 0);\">Khóa học dự bị AEIS cho học sinh quốc tế 7-15 tuổi. Thời gian 6 tháng.</em></blockquote>','/uploads/courses/thumbnails/593f4456-4ffe-48a3-9bfe-3372b7c7bd5c.png','linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)','GRADIENT','INTERMEDIATE',NULL,8220.00,NULL,0,1,'Lifetime','[\"sdddddddddddd\", \"dddddddd\"]','PUBLISHED','SELF_PACED','COMPLETION_BASED',2,NULL,'2026-09-12 00:38:55',NULL,NULL,'2026-08-21 12:43:37','2026-09-12 11:23:07','vi',NULL),(69,'Birmingham Academy - OSSD Canada (3 năm)','birmingham-ossd-canada','<p>Chương trình Bằng Tốt nghiệp Trung học Bang Ontario (OSSD) tại Singapore. Học sinh 14-18 tuổi.</p>','/uploads/courses/thumbnails/32ba0a2a-2cb5-41ba-a381-5198d22b1f61.png',NULL,NULL,'ALL_LEVELS',NULL,38019.00,NULL,0,1,'3 Years','[\"Bằng OSSD Canada\", \"Chuyển tiếp đại học toàn cầu\"]','DRAFT','LIVE',NULL,2,'cat-birmingham','2026-09-04 07:49:52',NULL,NULL,'2026-08-21 12:43:37','2026-09-04 07:56:27','vi',NULL),(70,'Birmingham Academy - Diploma Khách sạn 6+6','birmingham-diploma-khach-san-6-6','Chương trình Cao đẳng thực hành 6+6: 6 tháng học + 6 tháng thực tập có lương (1.100-1.800 SGD/tháng). Học bổng 40%.','/uploads/courses/thumbnails/32ba0a2a-2cb5-41ba-a381-5198d22b1f61.png',NULL,NULL,'ALL_LEVELS',NULL,4905.00,8131.00,0,1,'12 Months','[\"Bằng Diploma quốc tế\", \"Thực tập có lương\", \"Cơ hội S-PASS 85%\"]','PUBLISHED','LIVE','COMPLETION_BASED',2,'cat-birmingham','2026-08-21 12:43:37',NULL,NULL,'2026-08-21 12:43:37','2026-08-26 06:27:26','vi',NULL),(71,'Birmingham Academy - Diploma Logistics 6+6','birmingham-diploma-logistics-6-6','Chương trình Cao đẳng Logistics & Supply Chain 6+6: 6 tháng học + 6 tháng thực tập có lương. Học bổng 40%.','/uploads/courses/thumbnails/32ba0a2a-2cb5-41ba-a381-5198d22b1f61.png',NULL,NULL,'ALL_LEVELS',NULL,4905.00,8131.00,0,1,'12 Months','[\"Bằng Diploma quốc 