INSERT INTO `question` VALUES (201,68,'AEIS là viết tắt của cụm từ nào?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Admissions Exercise for International Students\"}, {\"label\": \"B\", \"content\": \"Asian Education International System\"}, {\"label\": \"C\", \"content\": \"Advanced English International School\"}, {\"label\": \"D\", \"content\": \"Association of Education in Singapore\"}]','[\"A\"]','AEIS là kỳ thi tuyển sinh dành cho học sinh quốc tế muốn vào trường công lập Singapore.','ACTIVE','2026-09-07 03:27:52','2026-09-07 13:40:20',0,1.00,100,'#lesson-100'),(202,68,'Kỳ thi AEIS dành cho học sinh ở độ tuổi nào?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"5-10 tuổi\"}, {\"label\": \"B\", \"content\": \"7-15 tuổi\"}, {\"label\": \"C\", \"content\": \"12-18 tuổi\"}, {\"label\": \"D\", \"content\": \"Mọi lứa tuổi\"}]','[\"B\"]','Kỳ thi AEIS dành cho học sinh quốc tế từ 7 đến 15 tuổi.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',1,1.00,100,'#lesson-100'),(203,68,'Kỳ thi AEIS được tổ chức mấy lần một năm?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"1 lần\"}, {\"label\": \"B\", \"content\": \"2 lần\"}, {\"label\": \"C\", \"content\": \"3 lần\"}, {\"label\": \"D\", \"content\": \"4 lần\"}]','[\"B\"]','AEIS được tổ chức 2 lần/năm (thường vào tháng 9-10 và có kỳ S-AEIS bổ sung vào tháng 2).','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',2,1.00,100,'#lesson-100'),(204,68,'Học sinh cần đạt trình độ tiếng Anh tối thiểu nào để tham gia khóa dự bị AEIS?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Beginner\"}, {\"label\": \"B\", \"content\": \"Elementary\"}, {\"label\": \"C\", \"content\": \"Intermediate\"}, {\"label\": \"D\", \"content\": \"Advanced\"}]','[\"B\"]','Học sinh cần có trình độ Elementary trở lên để bắt đầu khóa dự bị AEIS.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',3,1.00,100,'#lesson-100'),(205,68,'Kỳ thi AEIS kiểm tra những môn nào? (Chọn tất cả đáp án đúng)','MULTIPLE_CHOICE','[{\"label\": \"A\", \"content\": \"English Language\"}, {\"label\": \"B\", \"content\": \"Mathematics\"}, {\"label\": \"C\", \"content\": \"Science\"}, {\"label\": \"D\", \"content\": \"Social Studies\"}]','[\"A\", \"B\"]','Kỳ thi AEIS chỉ kiểm tra 2 môn: English Language và Mathematics.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',4,2.00,100,'#lesson-100'),(206,68,'Đọc đoạn văn: \"Singapore is a small island nation located in Southeast Asia. Despite its size, it has become one of the world\'s most prosperous countries...\" - Chủ đề chính của đoạn văn là gì?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Vị trí địa lý của Singapore\"}, {\"label\": \"B\", \"content\": \"Sự thịnh vượng của Singapore\"}, {\"label\": \"C\", \"content\": \"Lịch sử Singapore\"}, {\"label\": \"D\", \"content\": \"Ẩm thực Singapore\"}]','[\"B\"]','Đoạn văn nhấn mạnh sự thịnh vượng của Singapore dù là quốc gia nhỏ.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',0,1.00,103,'#lesson-103'),(207,68,'Trong đọc hiểu, \"skimming\" là kỹ thuật gì?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Đọc từng từ một cách cẩn thận\"}, {\"label\": \"B\", \"content\": \"Đọc lướt nhanh để nắm ý chính\"}, {\"label\": \"C\", \"content\": \"Đọc to thành tiếng\"}, {\"label\": \"D\", \"content\": \"Đọc và ghi chú chi tiết\"}]','[\"B\"]','Skimming là kỹ thuật đọc lướt nhanh để nắm ý chính của bài đọc.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',1,1.00,103,'#lesson-103'),(208,68,'\"Scanning\" trong đọc hiểu là gì?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Đọc toàn bộ bài\"}, {\"label\": \"B\", \"content\": \"Tìm kiếm thông tin cụ thể\"}, {\"label\": \"C\", \"content\": \"Đọc chậm từng câu\"}, {\"label\": \"D\", \"content\": \"Dịch sang tiếng Việt\"}]','[\"B\"]','Scanning là kỹ thuật tìm kiếm thông tin cụ thể trong bài đọc.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',2,1.00,103,'#lesson-103'),(209,68,'Những yếu tố nào giúp cải thiện kỹ năng đọc hiểu? (Chọn tất cả đáp án đúng)','MULTIPLE_CHOICE','[{\"label\": \"A\", \"content\": \"Mở rộng vốn từ vựng\"}, {\"label\": \"B\", \"content\": \"Luyện đọc thường xuyên\"}, {\"label\": \"C\", \"content\": \"Xem phim không phụ đề\"}, {\"label\": \"D\", \"content\": \"Học ngữ pháp cơ bản\"}]','[\"A\", \"B\", \"D\"]','Mở rộng từ vựng, luyện đọc thường xuyên và nắm ngữ pháp cơ bản đều giúp cải thiện đọc hiểu.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',3,2.00,103,'#lesson-103'),(210,68,'Khi gặp từ mới trong bài đọc, nên làm gì đầu tiên?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Tra từ điển ngay lập tức\"}, {\"label\": \"B\", \"content\": \"Đoán nghĩa từ ngữ cảnh\"}, {\"label\": \"C\", \"content\": \"Bỏ qua và đọc tiếp\"}, {\"label\": \"D\", \"content\": \"Hỏi giáo viên\"}]','[\"B\"]','Nên đoán nghĩa từ ngữ cảnh trước khi tra từ điển để rèn kỹ năng đọc.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',4,1.00,103,'#lesson-103'),(211,68,'Cấu trúc cơ bản của một bài luận gồm mấy phần?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"2 phần\"}, {\"label\": \"B\", \"content\": \"3 phần\"}, {\"label\": \"C\", \"content\": \"4 phần\"}, {\"label\": \"D\", \"content\": \"5 phần\"}]','[\"B\"]','Bài luận cơ bản gồm 3 phần: Introduction (Mở bài), Body (Thân bài), Conclusion (Kết luận).','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',0,1.00,106,'#lesson-106'),(212,68,'Phần Introduction (Mở bài) nên bao gồm những gì? (Chọn tất cả đáp án đúng)','MULTIPLE_CHOICE','[{\"label\": \"A\", \"content\": \"Hook (câu thu hút)\"}, {\"label\": \"B\", \"content\": \"Thesis statement (luận điểm chính)\"}, {\"label\": \"C\", \"content\": \"Background information\"}, {\"label\": \"D\", \"content\": \"Kết luận cuối cùng\"}]','[\"A\", \"B\", \"C\"]','Mở bài gồm hook, background information và thesis statement. Kết luận nằm ở cuối bài.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',1,2.00,106,'#lesson-106'),(213,68,'Câu nào sau đây là câu hoàn chỉnh về ngữ pháp?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"The students studies hard for the exam\"}, {\"label\": \"B\", \"content\": \"The students study hard for the exam\"}, {\"label\": \"C\", \"content\": \"The students studying hard for the exam\"}, {\"label\": \"D\", \"content\": \"The student study hard for the exam\"}]','[\"B\"]','\"The students study\" - chủ ngữ số nhiều đi với động từ nguyên mẫu.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',2,1.00,106,'#lesson-106'),(214,68,'Từ nối (transition word) nào phù hợp để thêm ý bổ sung?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"However\"}, {\"label\": \"B\", \"content\": \"Furthermore\"}, {\"label\": \"C\", \"content\": \"Therefore\"}, {\"label\": \"D\", \"content\": \"In contrast\"}]','[\"B\"]','\"Furthermore\" dùng để thêm ý bổ sung. \"However\" và \"In contrast\" chỉ sự tương phản, \"Therefore\" chỉ kết quả.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',3,1.00,106,'#lesson-106'),(215,68,'Thì nào thường được sử dụng trong bài luận học thuật?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Quá khứ đơn\"}, {\"label\": \"B\", \"content\": \"Hiện tại đơn\"}, {\"label\": \"C\", \"content\": \"Tương lai đơn\"}, {\"label\": \"D\", \"content\": \"Quá khứ tiếp diễn\"}]','[\"B\"]','Hiện tại đơn thường được dùng trong bài luận học thuật để trình bày sự thật và quan điểm.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',4,1.00,106,'#lesson-106'),(216,68,'Kết quả của phép tính: 3/4 + 1/2 = ?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"4/6\"}, {\"label\": \"B\", \"content\": \"5/4\"}, {\"label\": \"C\", \"content\": \"1 1/4\"}, {\"label\": \"D\", \"content\": \"2/3\"}]','[\"C\"]','3/4 + 1/2 = 3/4 + 2/4 = 5/4 = 1 1/4.','INACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',0,1.00,109,'#lesson-109'),(217,68,'25% của 200 là bao nhiêu?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"25\"}, {\"label\": \"B\", \"content\": \"50\"}, {\"label\": \"C\", \"content\": \"75\"}, {\"label\": \"D\", \"content\": \"100\"}]','[\"B\"]','25% = 25/100 = 1/4. 200 × 1/4 = 50.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',1,1.00,109,'#lesson-109'),(218,68,'Giá trị của x trong phương trình: 3x - 7 = 14 là bao nhiêu?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"x = 5\"}, {\"label\": \"B\", \"content\": \"x = 7\"}, {\"label\": \"C\", \"content\": \"x = 21\"}, {\"label\": \"D\", \"content\": \"x = 3\"}]','[\"B\"]','3x - 7 = 14 → 3x = 21 → x = 7.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',2,1.00,109,'#lesson-109'),(219,68,'Số nào sau đây là số nguyên tố? (Chọn tất cả đáp án đúng)','MULTIPLE_CHOICE','[{\"label\": \"A\", \"content\": \"2\"}, {\"label\": \"B\", \"content\": \"9\"}, {\"label\": \"C\", \"content\": \"13\"}, {\"label\": \"D\", \"content\": \"21\"}]','[\"A\", \"C\"]','2 và 13 là số nguyên tố. 9 = 3×3, 21 = 3×7.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',3,2.00,109,'#lesson-109'),(220,68,'Tỉ số của 15 và 45 được rút gọn là gì?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"1:2\"}, {\"label\": \"B\", \"content\": \"1:3\"}, {\"label\": \"C\", \"content\": \"2:3\"}, {\"label\": \"D\", \"content\": \"1:5\"}]','[\"B\"]','15/45 = 1/3. Tỉ số rút gọn là 1:3.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',4,1.00,109,'#lesson-109'),(221,68,'Tổng các góc trong một tam giác là bao nhiêu độ?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"90 độ\"}, {\"label\": \"B\", \"content\": \"180 độ\"}, {\"label\": \"C\", \"content\": \"270 độ\"}, {\"label\": \"D\", \"content\": \"360 độ\"}]','[\"B\"]','Tổng các góc trong một tam giác luôn bằng 180 độ.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',0,1.00,112,'#lesson-112'),(222,68,'Công thức tính diện tích hình chữ nhật là gì?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Dài × Rộng\"}, {\"label\": \"B\", \"content\": \"2 × (Dài + Rộng)\"}, {\"label\": \"C\", \"content\": \"Cạnh × Cạnh × Cạnh\"}, {\"label\": \"D\", \"content\": \"(Dài × Rộng) / 2\"}]','[\"A\"]','Diện tích hình chữ nhật = Chiều dài × Chiều rộng.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',1,1.00,112,'#lesson-112'),(223,68,'Một hình vuông có cạnh 5cm. Chu vi của hình vuông là bao nhiêu?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"10 cm\"}, {\"label\": \"B\", \"content\": \"15 cm\"}, {\"label\": \"C\", \"content\": \"20 cm\"}, {\"label\": \"D\", \"content\": \"25 cm\"}]','[\"C\"]','Chu vi hình vuông = 4 × cạnh = 4 × 5 = 20 cm.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',2,1.00,112,'#lesson-112'),(224,68,'Đường kính của hình tròn gấp mấy lần bán kính?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"1 lần\"}, {\"label\": \"B\", \"content\": \"2 lần\"}, {\"label\": \"C\", \"content\": \"3 lần\"}, {\"label\": \"D\", \"content\": \"π lần\"}]','[\"B\"]','Đường kính = 2 × bán kính.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',3,1.00,112,'#lesson-112'),(225,68,'Loại tam giác nào có một góc 90 độ?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Tam giác đều\"}, {\"label\": \"B\", \"content\": \"Tam giác cân\"}, {\"label\": \"C\", \"content\": \"Tam giác vuông\"}, {\"label\": \"D\", \"content\": \"Tam giác tù\"}]','[\"C\"]','Tam giác vuông là tam giác có một góc 90 độ.','ACTIVE','2026-09-07 03:27:52','2026-09-07 10:59:59',4,1.00,112,'#lesson-112'),(226,75,'Linux được phát triển dựa trên hệ điều hành nào?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Windows\"}, {\"label\": \"B\", \"content\": \"UNIX\"}, {\"label\": \"C\", \"content\": \"MS-DOS\"}, {\"label\": \"D\", \"content\": \"macOS\"}]','[\"B\"]','Linux dựa trên UNIX, phát triển từ thập niên 1970 tại AT&T Bell Labs','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',0,1.00,118,NULL),(227,75,'UNIX được phát triển vào thập niên nào?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"1950s\"}, {\"label\": \"B\", \"content\": \"1960s\"}, {\"label\": \"C\", \"content\": \"1970s\"}, {\"label\": \"D\", \"content\": \"1980s\"}]','[\"C\"]','UNIX ra đời những năm 1970 tại AT&T Bell Labs','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',1,1.00,118,NULL),(228,75,'UNIX được phát triển tại tổ chức nào?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Microsoft\"}, {\"label\": \"B\", \"content\": \"IBM\"}, {\"label\": \"C\", \"content\": \"AT&T Bell Labs\"}, {\"label\": \"D\", \"content\": \"Google\"}]','[\"C\"]','UNIX được phát triển tại AT&T Bell Labs','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',2,1.00,118,NULL),(229,75,'Linux là hệ điều hành có đặc điểm gì về mã nguồn?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Đóng, trả phí\"}, {\"label\": \"B\", \"content\": \"Miễn phí, mã nguồn mở\"}, {\"label\": \"C\", \"content\": \"Chỉ dùng nội bộ\"}, {\"label\": \"D\", \"content\": \"Không thể sửa đổi\"}]','[\"B\"]','Linux miễn phí và mã nguồn mở, khuyến khích cộng tác toàn cầu','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',3,1.00,118,NULL),(230,75,'Thành phần nào là lõi của hệ điều hành Linux?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Shell\"}, {\"label\": \"B\", \"content\": \"Desktop environment\"}, {\"label\": \"C\", \"content\": \"Linux kernel\"}, {\"label\": \"D\", \"content\": \"Package manager\"}]','[\"C\"]','Kernel là thành phần lõi, quản lý tài nguyên phần cứng và tiến trình','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',4,1.00,118,NULL),(231,75,'Thành phần nào cung cấp giao diện dòng lệnh cho người dùng?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Kernel\"}, {\"label\": \"B\", \"content\": \"Shell\"}, {\"label\": \"C\", \"content\": \"System Libraries\"}, {\"label\": \"D\", \"content\": \"Hardware Layer\"}]','[\"B\"]','Shell là giao diện dòng lệnh, thông dịch và thực thi lệnh người dùng','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',5,1.00,118,NULL),(232,75,'Thành phần nào giúp ứng dụng tương tác với kernel?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Shell\"}, {\"label\": \"B\", \"content\": \"System Libraries\"}, {\"label\": \"C\", \"content\": \"System Utilities\"}, {\"label\": \"D\", \"content\": \"Hardware Layer\"}]','[\"B\"]','System Libraries cung cấp các hàm giúp ứng dụng tương tác với kernel','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',6,1.00,118,NULL),(233,75,'Bản phân phối Linux nào thân thiện với người mới bắt đầu?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Arch Linux\"}, {\"label\": \"B\", \"content\": \"Ubuntu\"}, {\"label\": \"C\", \"content\": \"Kali Linux\"}, {\"label\": \"D\", \"content\": \"Gentoo\"}]','[\"B\"]','Ubuntu là distro thân thiện, dùng cho desktop, server và cloud','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',7,1.00,118,NULL),(234,75,'Bản phân phối nào chuyên về bảo mật và ethical hacking?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Debian\"}, {\"label\": \"B\", \"content\": \"Fedora\"}, {\"label\": \"C\", \"content\": \"Kali Linux\"}, {\"label\": \"D\", \"content\": \"Manjaro\"}]','[\"C\"]','Kali Linux là distro tập trung vào bảo mật, dùng cho penetration testing','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',8,1.00,118,NULL),(235,75,'Bản phân phối nào nổi tiếng với tính ổn định, dùng cho server?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Ubuntu\"}, {\"label\": \"B\", \"content\": \"Debian\"}, {\"label\": \"C\", \"content\": \"Fedora\"}, {\"label\": \"D\", \"content\": \"Solus\"}]','[\"B\"]','Debian ổn định và đáng tin cậy, được dùng rộng rãi cho server','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',9,1.00,118,NULL),(236,75,'Bản phân phối nào phù hợp với phần cứng cũ, nhẹ?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Ubuntu\"}, {\"label\": \"B\", \"content\": \"Manjaro\"}, {\"label\": \"C\", \"content\": \"MX Linux\"}, {\"label\": \"D\", \"content\": \"Fedora\"}]','[\"C\"]','MX Linux là distro nhẹ, phù hợp với phần cứng cũ','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',10,1.00,118,NULL),(237,75,'Bản phân phối nào dựa trên Arch và có rolling updates?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Debian\"}, {\"label\": \"B\", \"content\": \"Manjaro\"}, {\"label\": \"C\", \"content\": \"Ubuntu\"}, {\"label\": \"D\", \"content\": \"Solus\"}]','[\"B\"]','Manjaro dựa trên Arch, có rolling updates, thân thiện người dùng','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',11,1.00,118,NULL),(238,75,'Bản phân phối nào phù hợp với người dùng chuyển từ Windows?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Kali Linux\"}, {\"label\": \"B\", \"content\": \"Arch Linux\"}, {\"label\": \"C\", \"content\": \"Linux Mint\"}, {\"label\": \"D\", \"content\": \"Fedora\"}]','[\"C\"]','Linux Mint đơn giản, thân thiện, phù hợp người dùng Windows','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',12,1.00,118,NULL),(239,75,'Bản phân phối nào tập trung vào hiệu năng desktop và đơn giản?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Fedora\"}, {\"label\": \"B\", \"content\": \"Solus\"}, {\"label\": \"C\", \"content\": \"Debian\"}, {\"label\": \"D\", \"content\": \"openSUSE\"}]','[\"B\"]','Solus là distro hiện đại, tập trung vào hiệu năng desktop và đơn giản','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',13,1.00,118,NULL),(240,75,'Bản phân phối nào tập trung cho developer với công nghệ mới nhất?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Ubuntu\"}, {\"label\": \"B\", \"content\": \"Debian\"}, {\"label\": \"C\", \"content\": \"Fedora\"}, {\"label\": \"D\", \"content\": \"MX Linux\"}]','[\"C\"]','Fedora tập trung cho developer, tích hợp công nghệ mới nhất','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',14,1.00,118,NULL),(241,75,'Bản phân phối nào có giao diện đẹp mắt, dễ sử dụng?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Deepin\"}, {\"label\": \"B\", \"content\": \"Debian\"}, {\"label\": \"C\", \"content\": \"Arch Linux\"}, {\"label\": \"D\", \"content\": \"CentOS\"}]','[\"A\"]','Deepin có giao diện đẹp mắt, dễ sử dụng','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',15,1.00,118,NULL),(242,75,'Linux được dùng phổ biến trong lĩnh vực nào sau đây?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Chỉ máy tính cá nhân\"}, {\"label\": \"B\", \"content\": \"Chỉ điện thoại\"}, {\"label\": \"C\", \"content\": \"Server, cloud, cybersecurity, embedded...\"}, {\"label\": \"D\", \"content\": \"Chỉ máy chơi game\"}]','[\"C\"]','Linux dùng rộng rãi: server, cloud, development, cybersecurity, embedded, supercomputer','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',16,1.00,118,NULL),(243,75,'Hầu hết siêu máy tính (supercomputer) chạy hệ điều hành nào?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Windows\"}, {\"label\": \"B\", \"content\": \"macOS\"}, {\"label\": \"C\", \"content\": \"Linux\"}, {\"label\": \"D\", \"content\": \"UNIX độc quyền\"}]','[\"C\"]','Linux chạy trên hầu hết siêu máy tính cho tính toán khoa học','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',17,1.00,118,NULL),(244,75,'Để cài Linux, bước đầu tiên cần làm là gì?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"Mua USB mới\"}, {\"label\": \"B\", \"content\": \"Chọn bản phân phối Linux phù hợp\"}, {\"label\": \"C\", \"content\": \"Cài Windows trước\"}, {\"label\": \"D\", \"content\": \"Format ổ cứng\"}]','[\"B\"]','Bước đầu là chọn distro phù hợp (Ubuntu, Fedora, Linux Mint...)','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',18,1.00,118,NULL),(245,75,'Công cụ nào dùng để cài phần mềm trên Ubuntu/Debian?','SINGLE_CHOICE','[{\"label\": \"A\", \"content\": \"yum\"}, {\"label\": \"B\", \"content\": \"dnf\"}, {\"label\": \"C\", \"content\": \"apt\"}, {\"label\": \"D\", \"content\": \"pacman\"}]','[\"C\"]','apt là package manager của Ubuntu/Debian. dnf/yum cho Fedora/RHEL','ACTIVE','2026-09-13 09:21:59','2026-09-13 09:21:59',19,1.00,118,NULL);
